async function(descriptions){
 const x=load("producer_originals_current");if(!load("producer_originals_all_views_returned")||descriptions.length!==x.sources.length)throw Error("Actual source views/descriptions incomplete");
 if(x.views.some(v=>v.alpha_extrema[0]===0))throw Error("This completion helper requires an actually viewed complete painted rectangle, not a genuine exterior cutout");
 const done=(await tools.clock__curr_time({})).current_time.replace(" UTC","Z").replace(" ","T");
 const config={machine_id:"bf-202609141645-5434332d4d",actually_observed:true,observer:"Codex root; same generation executor, original input observation only",allocation:x.allocation,allocation_sha256:x.allocation_sha256,review_started_at_utc:load("producer_originals_view_started"),review_completed_at_utc:done,mascot_reference_sha256:x.mascot_reference_sha256,mascot_reference_observation:"Exact unchanged mascot reference actually viewed earlier in this same root turn; reused SHA-bound observation, not claimed freshly viewed inside this group interval.",sources:x.sources.map((s,i)=>({key:s.key,description:'Standalone full painted rectangle. '+descriptions[i]})),held:{},viewed_originals:x.views.map(v=>({key:v.key,path:v.path,sha256:v.sha256,size:v.size,alpha_extrema:v.alpha_extrema,actual_native_view:true,nearest_path:v.nearest_path,nearest_sha256:v.nearest_sha256,actual_nearest4_view:true})),scope:"Finite actual original input preparation by existing root generation executor while a/b continue PNG review. No third portrait-review slot, new agent, output approval or image generation. Complete only queues an immutable preparation intent; sole producer rechecks HIGH/service/attempt/input gates."};
 await tools.apply_patch("*** Begin Patch\n*** Add File: C:/workspace/xenoamess_hoi4_dev/"+x.config+"\n+"+JSON.stringify(config,null,2).replaceAll("\n","\n+")+"\n*** End Patch");
 const r=await tools.exec_command({cmd:"python -X utf8 tools\\fresh_source_observation_queue.py complete "+x.config,shell:"cmd.exe",login:false,max_output_tokens:1800});
 if(r.exit_code!==0)throw Error(JSON.stringify(r));text(r.output);store("producer_originals_group_completed",x.tag);
}
